CREATE TABLE summary_settings(group_id uuid PRIMARY KEY REFERENCES groups(id),revision integer NOT NULL DEFAULT 1,config jsonb NOT NULL,last_adapter_seen timestamptz);
CREATE TABLE summary_templates(slug text PRIMARY KEY,name text NOT NULL,instructions text NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE TABLE summary_schedules(id uuid PRIMARY KEY,group_id uuid NOT NULL REFERENCES groups(id),name text NOT NULL,enabled boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,config jsonb NOT NULL,next_run timestamptz NOT NULL,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE summary_jobs(id uuid PRIMARY KEY,group_id uuid NOT NULL REFERENCES groups(id),external_id text NOT NULL,group_revision integer NOT NULL,settings_revision integer NOT NULL,request_id uuid NOT NULL UNIQUE,schedule_id uuid REFERENCES summary_schedules(id),occurrence timestamptz,status text NOT NULL DEFAULT 'waiting_source',wants_publish boolean NOT NULL,window_start timestamptz NOT NULL,window_end timestamptz NOT NULL,config jsonb NOT NULL,template jsonb NOT NULL,source jsonb,report text,error text,source_token uuid,delivery_token uuid,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(schedule_id,occurrence));
CREATE TABLE summary_parts(job_id uuid REFERENCES summary_jobs(id),ordinal integer NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'waiting',PRIMARY KEY(job_id,ordinal));
CREATE INDEX summary_jobs_pending ON summary_jobs(status,created_at);
CREATE INDEX summary_jobs_group ON summary_jobs(group_id,created_at DESC);
